 @Test void staleExpectedVersionDoesNotMutate(){var r=mock(LeaveRequestRepository.class);var request=mock(LeaveRequestEntity.class);var id=UUID.randomUUID();when(r.lockDirectReport(id,id)).thenReturn(Optional.of(request));when(request.getEmployeeId()).thenReturn(UUID.randomUUID());when(request.getVersion()).thenReturn(3L);var s=new ManagerDecisionService(r,mock(LeaveRequestBalanceLineRepository.class),mock(LeaveBalanceRepository.class),mock(LeaveBalanceMovementRepository.class),mock(LeaveRequestSlotRepository.class),mock(LeaveRequestStatusHistoryRepository.class),mock(AuditEventRepository.class),mock(LeavePolicyQueryService.class),mock(ManagerLeaveRequestQueryService.class));var actor=new CurrentActor(UUID.randomUUID(),id,null,Set.of("MANAGER"),"Manager");assertThatThrownBy(()->s.decide(actor,id,2L,null,true)).isInstanceOf(DomainException.class).hasMessageContaining("changed");verify(r,never()).saveAndFlush(any());}
